---@alias gcp.datamigration_v1.MigrationJobObjectStateEnum "STATE_UNSPECIFIED"|"NOT_STARTED"|"RUNNING"|"STOPPING"|"STOPPED"|"RESTARTING"|"FAILED"|"REMOVING"|"NOT_SELECTED"|"COMPLETED"

